<script>
import { mapGetters } from 'vuex'
export default {
  name: 'productInfo',
  data () {
    return {
      accountInfo: {}
    }
  },
  methods: {
    doCopy () {
      this.$copy('rita@waimaolang.cn')
    },
    goWeb () {
      window.open('https://www.waimaolang.cn')
    }
  },
  created () {
    this.SharpObj.getAccountInfo(res => {
      res = JSON.parse(res)
      let errorMsg = this.$WmlValidator.validate(res.Code, [{ rule: 'isNumberEq:0', errorMsg: res.Msg }])
      if (errorMsg) {
        this.$WmlMsg(errorMsg, 'warning')
      } else {
        this.accountInfo = res.Data
      }
    })
  },
  computed: {
    ...mapGetters(['getterVersion'])
  }
}
</script>

