<template>
  <div
    class="panel-main"
    v-loading="getterLoading.loading"
    :element-loading-text="getterLoading.tit"
    element-loading-spinner="el-icon-loading"
    element-loading-background="rgb(255,255,255)"
  >
    <div class="form-content">
      <el-divider content-position="left">{{ $lang('public.gsInsAutoFollow', '自动关注') }}</el-divider>
      <div>
        <div class="text-content">
          <span
            style="margin-right:18px"
          >{{ $lang('public.gsInsCompanyMarketingLimit', '同一公司营销上限') }}</span>
          <el-input-number
            size="mini"
            controls-position="right"
            v-model="getterInstagramItem.CompanyLimit"
          ></el-input-number>
        </div>
      </div>
      <div class="form-item">
        <div class="form-item-tit">
          <el-checkbox
            v-model="getterInstagramItem.IsFollow"
            disabled
          >{{ $lang('public.gsInsAutoFollow', '自动关注') }}</el-checkbox>
        </div>
        <div class="form-item-content">
          <div class="form-item-option">
            <div class="text-tit">{{ $lang('public.gsInsMsgSend', '消息发送') }}</div>
            <div class="text-content">
              <el-input
                style="width:300px"
                type="textarea"
                :rows="10"
                :placeholder="$lang('public.gsInsContentInputTip', '请输入内容')"
                v-model="getterInstagramItem.Message"
              ></el-input>
            </div>
          </div>
        </div>
      </div>
      <el-divider content-position="left">{{ $lang('public.gsInsUnfollow', '取消关注') }}</el-divider>
      <div class="form-item">
        <div class="form-item-tit">
          <el-checkbox
            v-model="getterInstagramItem.IsUnfollow"
          >{{ $lang('public.gsInsAutoUnfollow', '自动取消关注') }}</el-checkbox>
        </div>
        <div class="form-item-content">
          <div class="form-item-option option-flex">
            <div class="number-tit">{{ $lang('public.gsInsCancelLimit', '取消阈值') }}</div>
            <div class="text-content">
              <el-input-number
                v-model="getterInstagramItem.UnFollowThreshold"
                controls-position="right"
                :min="0"
                size="mini"
              ></el-input-number>
            </div>
          </div>
          <wml-tip
            :simple-tip="$lang('public.gsInsCancelLimitSimpleTip', '达到该数量时取消关注')"
            :detail-tip="$lang('public.gsInsCancelLimitDetailTip', '每个instagram账号都有关注上限，达到上限将无法继续关注。设定一个取关阈值，关注数量达到该值时，程序会帮助用户自动取消关注。')"
          ></wml-tip>
          <div class="form-item-option option-flex">
            <div class="number-tit">{{ $lang('public.gsInsUnfollowRange', '每日取关范围') }}</div>
            <div class="text-content">
              <el-input-number
                v-model="getterInstagramItem.MinUnfollowNumber"
                controls-position="right"
                :min="0"
                size="mini"
              ></el-input-number>
              <span style="margin:0 10px">~</span>
              <el-input-number
                v-model="getterInstagramItem.MaxUnfollowNumber"
                controls-position="right"
                :min="0"
                size="mini"
              ></el-input-number>
              <span style="margin-left:10px">{{ $lang('common.unit', '个') }}</span>
            </div>
          </div>
          <wml-tip
            :simple-tip="$lang('public.gsInsUnfollowRangeSimpleTip', '每日取消关注的范围')"
            :detail-tip="$lang('public.gsInsUnfollowRangeDetailTip', '每天取关同样数量的账号，会让平台判定为机械人操作。设定一个取关范围会让程序更像人为操作。')"
          ></wml-tip>
        </div>
      </div>
    </div>
    <div class="form-button">
      <el-button type="primary" style="width:300px" @click="doSave">{{ $lang('common.saveBtn', '保存') }}</el-button>
    </div>
  </div>
</template>
<script>
import { mapGetters, mapActions } from 'vuex'
export default {
  name: 'insGlobalSetting',
  data () {
    return {
      checked: false,
      textarea: '',
      num: 10
    }
  },
  methods: {
    ...mapActions(['dispatchChangeLoading']),
    /**
     * @author: vince.Liang
     * @function: 保存ins全局营销设置
     * @data: 2019-3-27
     * @param {none}
     * @return:undefined
     */
    doSave () {
      this.dispatchChangeLoading({ loading: true, tit: this.$lang('common.saveing', '保存中') })
      this.SharpObj.setTaskDefaultConfig(JSON.stringify(this.getterInstagram), res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          this.$WmlMsg(this.$lang('common.saveSuccess', '保存成功！'))
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
        this.dispatchChangeLoading({ loading: false })
      })
    }
  },
  computed: {
    ...mapGetters(['getterInstagram', 'getterInstagramItem', 'getterLoading'])
  }
}
</script>
<style scoped>
.panel-main {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.form-content {
  flex-grow: 1;
  overflow: auto;
}

.form-item-tit {
  padding: 10px 0;
}

.form-item-content {
  padding-left: 30px;
}

.text-tit {
  height: 30px;
  line-height: 30px;
}

.form-button {
  flex-shrink: 0;
  padding-top: 10px;
  text-align: center;
}

.option-flex {
  display: flex;
  padding: 10px 0;
  align-items: center;
}

.number-tit {
  width: 120px;
}
</style>
