<template>
  <transition name="fade">
    <div class="main-height toggle-hover">
      <div class="toggle-btn">
        <div class="show-nav-toggle" @click="changeCollapse">
          <i :class="!isCollapse?'el-icon-caret-left':'el-icon-caret-right'"></i>
        </div>
      </div>
      <div class="wml-scroll" :style="toggleStyle">
        <menu-content :shortShow="isCollapse" v-bind="$attrs" @handleLeftIcon="handleLeftIcon"></menu-content>
      </div>
    </div>
  </transition>
</template>

<script>
import { mapGetters, mapActions } from 'vuex'
import menuContent from './menuContent'
export default {
  name: 'leftNav',
  components: { menuContent },
  data () {
    return {
      showMenuStyle: {},
      toggleStyle: {},
      isCollapse: false
    }
  },
  methods: {
    ...mapActions(['changeMenus']),
    getMenuList () {
      this.$api.menuList().then(res => {
        this.changeMenus(res.data.data.menus)
      })
    },
    handleLeftIcon (type) {
      this.$emit('handleLeftIcon', type)
    },

    changeCollapse () {
      this.isCollapse = !this.isCollapse
      this.$bus.$emit('resizeMarketingEchart', '123')
    }
  },
  computed: {
    ...mapGetters(['routes'])
  },
  watch: {
    isCollapse (val) {
      if (val) {
        this.showMenuStyle = { left: 0, right: 0 }
        this.toggleStyle = { width: '85px' }
      } else {
        this.showMenuStyle = { right: 0 }
        this.toggleStyle = { width: '360px' }
      }
    }
  }
}
</script>

<style  rel="stylesheet/scss" lang="scss" scoped>
$hoverLineColor: #429efc;
$hoverBefore: #ccc;
.toggle-hover {
  border-right: 1px transparent;
  &:hover {
    .toggle-btn {
      // visibility: hidden;
      // visibility: block;
      display: block;
      background: linear-gradient(
        to bottom,
        transparent,
        $hoverLineColor,
        transparent
      );
      .show-nav-toggle {
        color: $hoverLineColor;
        border-right: 1px solid $hoverLineColor;
        cursor: pointer;
        &::before {
          border-top: 1px solid $hoverLineColor;
        }
        &:after {
          border-bottom: 1px solid $hoverLineColor;
        }
      }
    }
  }
}
.toggle-btn {
  display: none;
  position: absolute;
  width: 1px;
  right: -1px;
  height: 100%;
  z-index: 1000;
  background: $hoverBefore;
}
.show-nav-toggle {
  border: 1px solid transparent;
  position: absolute;
  width: 15px;
  top: calc(50% - 50px);
  height: 100px;
  z-index: 1000;
  background: #e8eff4;
  background-size: 100% 50%;
  background-repeat: no-repeat;
  border-left: 0;
  text-align: center;
  display: table;
  border-right: 1px solid #ccc;
  i {
    display: table-cell;
    vertical-align: middle;
  }
  &:before,
  &:after {
    position: absolute;
    border: 1px transparent;
    content: "";
    width: 14px;
    height: 15px;
    background: #e8eff4;
    left: 0px;
    transform: rotate(45deg);
    transform: skewY(45deg);
  }
  &:before {
    top: -9px;
    border-top: 1px solid #ccc;
    border-right: 1px solid;
  }
  &:after {
    bottom: -9px;
    transform: rotate(-45deg);
    transform: skewY(-45deg);
    border-right: 1px solid;
    border-bottom: 1px solid #ccc;
  }
}
.wml-scroll {
  min-width: 85px;

  height: calc(100% - 0px);
  position: relative;
  left: 0;
  right: 0;
  bottom: 0;
}
.logo {
  position: absolute;
  left: 0;
  top: 0;
  right: 45px;
  z-index: 9;
  height: 45px;
  .logo-img {
    width: 100%;
    height: 100%;
    object-fit: contain;
  }
}
.show-menu {
  i {
    font-size: 20px;
  }
  display: inline-block;
  text-align: center;
  margin: 0 auto;
  height: 45px;
  width: 45px;
  // font-size: 20px;
  line-height: 45px;
  position: absolute;
  // left: 0;
  top: 0;
  right: 0;
  z-index: 10;
}
.el-menu-vertical-wml {
  // padding-top: 45px;
  border-right: 0;
  height: calc(100% - 0px);
  max-height: calc(100% - 0px);
  position: relative;
  left: 0;
  right: 0;
  bottom: 0;
  top: 0px;
  overflow-y: auto;
  &:not(.el-menu--collapse) {
    width: 200px;
  }
}
// .el-menu-vertical-wml:not(.el-menu--collapse) /deep/ {
// }
</style>
