<template>
  <div
    class="panel-box"
    v-loading="getterLoading.loading"
    :element-loading-text="getterLoading.tit"
    element-loading-spinner="el-icon-loading"
    element-loading-background="rgb(255,255,255)"
  >
    <div class="email-wrap-box">
      <div class="email-wrap">
        <div class="action-time-box">
          <el-divider
            content-position="left"
            style="margin-bottom:0px"
          >{{ $lang('public.gsActionExecuteTime', '执行时间') }}</el-divider>
          <wml-tip
            :simple-tip="$lang('public.gsActionExecuteTimeSimpleTip', '自动执行营销任务时间段')"
            :detail-tip="$lang('public.gsActionExecuteTimeDetailTip', '自动营销任务的执行时间段，请尽量选择在日间和非休息时间来执行任务，例如 08:00~12:00 和14:00~22:00')"
          ></wml-tip>
          <div
            class="email-option"
            v-for="(item, index) of getterActionItem.ExecuteTimeList"
            :key="index"
          >
            <div>
              <el-time-picker
                size="mini"
                v-model="item.StartTime"
                :placeholder="$lang('public.gsActionStartTimeInputTip', '开始时间')"
                style="width:130px"
                value-format="HH:mm"
                format="HH:mm"
              ></el-time-picker>
              <span style="margin:0 10px">~</span>
              <el-time-picker
                size="mini"
                value-format="HH:mm"
                format="HH:mm"
                v-model="item.EndTime"
                :placeholder="$lang('public.gsActionEndTimeInputTip', '结束时间')"
                style="width:130px"
              ></el-time-picker>
            </div>
            <div class="action-time-action">
              <i
                class="action-action-add el-icon-circle-plus-outline"
                v-if="index === getterActionItem.ExecuteTimeList.length - 1"
                @click="handleExecute('add', index)"
              ></i>
              <i
                class="action-action-reduce el-icon-remove-outline"
                v-if="getterActionItem.ExecuteTimeList.length > 1"
                @click="handleExecute('reduce', index)"
              ></i>
            </div>
          </div>
        </div>
        <el-divider content-position="left">{{ $lang('public.gsActionTimeSelect', '时间选择') }}</el-divider>
        <wml-tip
          :simple-tip="$lang('public.gsActionTimeSelectSimpleTip', '自动执行营销任务的日期')"
          :detail-tip="$lang('public.gsActionTimeSelectDetailTip', '请勾选您需要自动执行营销任务的日期，系统将会在当日自动执行营销任务！')"
        ></wml-tip>
        <div style="padding:10px 0">
          <el-checkbox
            style="margin-bottom:10px"
            :indeterminate="isIndeterminate"
            v-model="checkAll"
            @change="handleCheckAllChange"
          >{{ $lang('public.gsActionCheckAll', '全选') }}</el-checkbox>
          <el-checkbox-group v-model="getterActionItem.DayOfWeek">
            <el-checkbox
              v-for="(item, index) of DayOfWeekOption"
              :key="index"
              :label="item.key"
            >{{item.label}}</el-checkbox>
          </el-checkbox-group>
        </div>
        <el-divider content-position="left">{{ $lang('public.gsActionOperationSetting', '操作设置') }}</el-divider>
        <div style="padding-top:10px">
          <div class="email-set-row" style="padding-bottom:10px">
            <div class="email-set-option">
              <div
                class="email-set-tit linin-tit-left"
                style="width:100px;padding-right:10px"
                :class="{'linin-tit-en':$i18n.locale === 'en'}"
              >
                <div>{{ $lang('public.gsActionExecuteInterval', '执行间隔') }}</div>
              </div>
              <div class="email-set-content" style="display:flex;align-items:center">
                <el-input-number
                  size="mini"
                  controls-position="right"
                  v-model="getterActionItem.ExecutionDelay.MinDelay"
                ></el-input-number>
                <div style="margin:0 10px">~</div>
                <el-input-number
                  size="mini"
                  controls-position="right"
                  v-model="getterActionItem.ExecutionDelay.MaxDelay"
                ></el-input-number>
                <div style="margin-left:10px">{{ $lang('common.unitSecond', '秒') }}</div>
              </div>
            </div>
          </div>
          <wml-tip
            :simple-tip="$lang('public.gsActionExecuteIntervalSimpleTip', '如邮件的发送间隔、LinkedIn的营销间隔')"
            :detail-tip="$lang('public.gsActionExecuterIntervalDetailTip', '邮件发送完毕后到下一封邮件发送的间隔时间范围，下一个社交平台账号执行营销任务的间隔时间范围。过于频繁的执行营销操作会让社交平台判定我们的社交账号存在异常，是机器人而非人工操作，填写一定操作间隔范围，程序会自动生成一个随机的时间间隔来执行营销操作，降低被封号的风险。推荐(30~60秒)')"
          ></wml-tip>
        </div>

        <div style="padding-top:10px">
          <div class="email-set-row" style="padding-bottom:10px">
            <div class="email-set-option">
              <div
                class="email-set-tit linin-tit-left"
                style="width:100px;padding-right:10px"
                :class="{'linin-tit-en':$i18n.locale === 'en'}"
              >
                <div>{{ $lang('public.gsActionOperationInterval', '操作间隔') }}</div>
              </div>
              <div class="email-set-content" style="display:flex;align-items:center">
                <el-input-number
                  size="mini"
                  controls-position="right"
                  v-model="getterActionItem.OperationDelay.MinDelay"
                ></el-input-number>
                <div style="margin:0 10px">~</div>
                <el-input-number
                  size="mini"
                  controls-position="right"
                  v-model="getterActionItem.OperationDelay.MaxDelay"
                ></el-input-number>
                <div style="margin-left:10px">{{ $lang('common.unitSecond', '秒') }}</div>
              </div>
            </div>
          </div>
          <wml-tip
            :simple-tip="$lang('public.gsActionOperationIntervalSimpleTip', '如LinkenIn添加好友和写入验证信息的间隔范围')"
            :detail-tip="$lang('public.gsActionOperationIntervalDetailTip', '人工操作执行社交账号的营销，每一个操作步骤的时间是不固定的。填写一定操作间隔范围，程序会自动生成一个随机的时间间隔来执行营销的操作步骤，这样会让程序的营销操作更加的人性化，也能让社交平台认为这是人工操作而非机器人，降低被封号的风险。 推荐(5~15秒)。')"
          ></wml-tip>
        </div>

        <div style="padding-top:10px">
          <!-- <div class="email-set-row" style="padding-bottom:10px">
            <div class="email-set-option">
              <div
                class="email-set-tit linin-tit-left"
                style="width:100px;padding-right:10px"
              >{{ $lang('public.gsActionTaskTraceInterval', '任务追踪间隔') }}</div>
              <div class="email-set-content" style="margin-right:10px">
                <el-input-number
                  size="mini"
                  controls-position="right"
                  v-model="getterActionItem.TaskTrackingTime"
                ></el-input-number>
                <span style="margin-left:10px">{{ $lang('common.unitDay', '天') }}</span>
              </div>
            </div>
          </div>-->
          <!-- <wml-tip
            :simple-tip="$lang('public.gsActionTaskTraceIntervalSimpleTip', '对每个营销对象执行营销任务的间隔时间')"
            :detail-tip="$lang('public.gsActionTaskTraceIntervalDetailTip', '每个公司有多个邮箱和多个员工社交账号,为了降低社交账号和邮件账号被封号的风险，程序每次执行邮件发送和社交平台营销只会执行用户选择数据(如同一个公司邮件发送上限，同一公司好友添加上限)。在任务全部执行完毕之后，达到设定间隔会追踪并继续执行任务。')"
          ></wml-tip>-->
        </div>
        <div style="padding:10px 0">
          <div class="email-set-option" style="padding-bottom:10px">
            <div
              class="email-set-tit"
              style="text-align:left;width:100px;padding-right:10px;margin-right:17px"
              :class="{'linin-tit-en':$i18n.locale === 'en'}"
            >{{ $lang('public.gsActionTaskLimit', '每日任务上限') }}</div>
            <div class="email-set-content">
              <el-input-number
                size="mini"
                controls-position="right"
                v-model="getterActionItem.TaskLimitEveryDay"
              ></el-input-number>
            </div>
          </div>
          <wml-tip
            :simple-tip="$lang('public.gsActionTaskLimitSimpleTip', '每天执行营销任务的限制')"
            :detail-tip="$lang('public.gsActionTaskLimitDetailTip', '由于过于频繁的操作容易导致被停封账号，因此我们建议您设定合理的任务限制')"
          ></wml-tip>
        </div>
      </div>
    </div>
    <div class="email-btn-box">
      <el-button
        style="width:300px"
        type="primary"
        @click="doSave"
      >{{ $lang('common.saveBtn', '保存') }}</el-button>
    </div>
  </div>
</template>

<script>
import { mapGetters, mapActions } from 'vuex'
const week = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
export default {
  data () {
    return {
      input: '',
      DayOfWeekOption: [
        {
          label: this.$lang('common.monday', '星期一'),
          key: 'Monday'
        },
        {
          label: this.$lang('common.tuesday', '星期二'),
          key: 'Tuesday'
        },
        {
          label: this.$lang('common.wednesday', '星期三'),
          key: 'Wednesday'
        },
        {
          label: this.$lang('common.thursday', '星期四'),
          key: 'Thursday'
        },
        {
          label: this.$lang('common.friday', '星期五'),
          key: 'Friday'
        },
        {
          label: this.$lang('common.saturday', '星期六'),
          key: 'Saturday'
        },
        {
          label: this.$lang('common.sunday', '星期日'),
          key: 'Sunday'
        }
      ],
      isIndeterminate: true,
      checkAll: false
    }
  },
  methods: {
    ...mapActions(['dispatchChangeLoading']),
    handleCheckAllChange (val) {
      this.getterActionItem.DayOfWeek = val ? week : []
      this.isIndeterminate = false
    },
    handleCheckedWeekChange (val) {
      let weekLength = val.length
      this.checkAll = week.length === weekLength
      this.isIndeterminate = weekLength > 0 && weekLength < week.length
    },
    doSave () {
      this.dispatchChangeLoading({ loading: true, tit: this.$lang('common.saveing', '保存中') })
      this.SharpObj.setTaskDefaultConfig(JSON.stringify(this.getterAction), res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          this.$WmlMsg(this.$lang('common.saveSuccess', '保存成功！'))
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
        this.dispatchChangeLoading({ loading: false })
      })
    },

    /**
     * @author: vince.Liang
     * @function: 处理执行时间条件的添加或者减少
     * @data: 2019-3-27
     * @param {String} type 操作标识，添加或者减少
     * @param {Number} index 当前操作的位置
     * @return: undefined
     */
    handleExecute (type, index) {
      if (type === 'add') {
        this.getterActionItem.ExecuteTimeList.push({
          StartTime: '',
          EndTime: ''
        })
      }
      if (type === 'reduce') {
        this.getterActionItem.ExecuteTimeList.splice(index, 1)
      }
    }
  },
  computed: {
    ...mapGetters([
      'getterLoading',
      'getterAction',
      'getterActionItem'
    ])
  },
  watch: {
    'getterActionItem.DayOfWeek': function (val) {
      this.handleCheckedWeekChange(val)
    }
  }
}
</script>
