<template>
  <div
    class="panel-box"
    v-loading="getterLoading.loading"
    :element-loading-text="getterLoading.tit"
    element-loading-spinner="el-icon-loading"
    element-loading-background="rgb(255,255,255)"
  >
    <div class="email-wrap-box">
      <div class="email-wrap">
        <el-divider content-position="left">{{ $lang('public.gsTwitterAddFriendList', '加入好友列表') }}</el-divider>
        <div class="email-option">
          <div
            class="email-set-tit linin-tit-left"
            style="width:auto;"
          >{{ $lang('public.gsTwitterCompanyMarketingLimit', '同一公司营销上限') }}</div>
          <div class="email-set-content">
            <el-input-number
              size="mini"
              controls-position="right"
              v-model="getterTwitterItem.CompanyLimit"
            ></el-input-number>
          </div>
        </div>
        <div class="email-option">
          <div class="email-tit">
            <el-checkbox
              v-model="getterTwitterItem.IsAddFriendList"
            >{{ $lang('public.gsTwitterIsNoAddFriendList', '是否加入好友列表') }}</el-checkbox>
          </div>
        </div>
        <div class="email-option">
          <div class="email-tit">
            <el-checkbox
              v-model="getterTwitterItem.IsTheFriendList"
              disabled
            >{{ $lang('public.gsTwitterDefaultFirstList', '默认第一个好友列表') }}</el-checkbox>
          </div>
        </div>
        <div class="email-option">
          <div>
            <el-checkbox
              v-model="getterTwitterItem.IsGenerateList"
              disabled
            >{{ $lang('public.gsTwitterAutoCreateList', '无列表自动生成') }}</el-checkbox>
          </div>
          <div class="email-content" style="margin-left:30px">
            <div class="email-set-row" style="padding-bottom:0px">
              <div class="email-set-option">
                <div
                  class="email-set-tit linin-tit-left"
                  style="width:auto;"
                >{{ $lang('public.gsTwitterListName', '列表名') }}</div>
                <div class="email-set-content">
                  <el-input
                    v-model="getterTwitterItem.FriendListName"
                    size="mini"
                    style="width:300px"
                  ></el-input>
                </div>
              </div>
            </div>
          </div>
        </div>
        <div class="email-option">
          <div class="email-tit">
            <el-checkbox
              v-model="getterTwitterItem.IsFilter"
              disabled
            >{{ $lang('public.gsTwitterFilterContact', '过滤无法发送消息的联系人') }}</el-checkbox>
          </div>
        </div>
        <el-divider content-position="left">{{ $lang('public.gsTwitterMsgSend', '信息发送') }}</el-divider>
        <div style="padding-bottom:10px">
          <!-- <el-checkbox style="margin-bottom:10px" v-model="getterTwitterItem.IsSendMsg">是否发送消息</el-checkbox> -->
          <div class="email-set-row" style="padding:10px 0">
            <div class="email-set-option" style="width:100%;padding-right:38px">
              <div
                class="email-set-tit"
                style="width:auto"
              >{{ $lang('public.gsTwitterMsgContent', '消息内容') }}</div>
              <div style="flex-grow:1">
                <el-input
                  type="textarea"
                  v-model="getterTwitterItem.MsgContent"
                  rows="10"
                  size="mini"
                ></el-input>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <div class="email-btn-box">
      <el-button
        style="width:300px"
        type="primary"
        @click="doSave"
      >{{ $lang('common.saveBtn', '保存') }}</el-button>
    </div>
  </div>
</template>
<script>
import { mapGetters, mapActions } from 'vuex'
export default {
  data () {
    return {}
  },
  methods: {
    ...mapActions(['dispatchChangeLoading']),
    doSave () {
      this.dispatchChangeLoading({ loading: true, tit: this.$lang('common.saveing', '保存中') })
      this.SharpObj.setTaskDefaultConfig(JSON.stringify(this.getterTwitter), res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          this.$WmlMsg(this.$lang('common.saveSuccess', '保存成功！'))
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
        this.dispatchChangeLoading({ loading: false })
      })
    }
  },
  computed: {
    ...mapGetters(['getterTwitter', 'getterTwitterItem', 'getterLoading'])
  },
  watch: {
    'getterTwitterItem.IsAddFriendList' (val) {
      this.getterTwitterItem.IsTheFriendList = this.getterTwitterItem.IsGenerateList = this.getterTwitterItem.IsFilter = val
    }
  }
}
</script>
<style scoped>
