  width: 100px;
}

.email-set-box {
}

.email-set-row {
  display: flex;
  padding-bottom: 17px;
}

.email-set-option {
  display: flex;
  align-items: center;
}

.email-set-tit {
  text-align: right;
  margin-right: 17px;
}

.email-btn-box {
  padding-top: 10px;
  text-align: center;
  flex-shrink: 0;
  margin-top: auto;
}

.linin-tit-left {
  text-align: left;
}

.panel-box {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.email-wrap-box {
  flex-grow: 1;
  width: 100%;
  overflow: hidden;
}

