<template>
  <div
    class="panel-box"
    v-loading="getterLoading.loading"
    :element-loading-text="getterLoading.tit"
    element-loading-spinner="el-icon-loading"
    element-loading-background="rgb(255,255,255)"
  >
    <div class="email-wrap-box">
      <div class="email-wrap">
        <el-divider content-position="left">{{ $lang('public.gsEmailSettingTit', '邮箱设置') }}</el-divider>
        <div
          class="email-option"
          v-for="(item, index) of getterEmailItem.EmailTypeList"
          :key="index"
        >
          <div class="email-tit" style="width:170px">
            <el-checkbox v-model="item.IsTick" :disabled="!item.CanUse">
              {{item.EmailName}}
              <i class="el-icon-success email-success" v-if="item.CanUse"></i>
              <i class="el-icon-error email-fail" v-if="!item.CanUse"></i>
            </el-checkbox>
          </div>
          <div class="email-content" style="flex-grow:1;">
            <div class="email-set-row" style="padding-bottom:0px">
              <div class="email-set-option">
                <div
                  class="email-set-tit linin-tit-left"
                  style="width:auto;"
                >{{ $lang('public.gsEmailSendLimit', '每日发送上限') }}</div>
                <div class="email-set-content">
                  <el-input-number
                    :min="10"
                    size="mini"
                    controls-position="right"
                    v-model="item.SendLimit"
                  ></el-input-number>
                  <span style="margin-left:10px">{{ $lang('common.unitSeal', '封') }}</span>
                </div>
              </div>
            </div>
          </div>
        </div>

        <el-divider content-position="left">{{ $lang('public.gsEmailContent', '邮件内容') }}</el-divider>
        <div class="email-set-option">
          <div
            class="email-set-tit linin-tit-left"
            style="padding-right:10px"
          >{{ $lang('public.gsEmailCompanyEmailSendLimit', '同一公司邮件发送上限') }}</div>
          <div class="email-set-content">
            <el-input-number
              size="mini"
              controls-position="right"
              v-model="getterEmailItem.CompanySendLimit"
              :min="1"
              :max="100"
            ></el-input-number>
            <span style="margin-left:10px">{{ $lang('common.unitSeal', '封') }}</span>
          </div>
        </div>

        <div style="padding-bottom:10px">
          <div class="email-set-row" style="padding:10px 0">
            <div class="email-set-option" style="width:100%;padding-right:38px">
              <div
                class="email-set-tit"
                style="width:auto"
                :class="{'linin-tit-en':$i18n.locale === 'en'}"
              >
                {{ $lang('public.gsEmailTitle', '邮件标题') }}
                <span style="color:#F64D60">*</span>
              </div>
              <div style="flex-grow:1">
                <el-input v-model="getterEmailItem.Theme"></el-input>
              </div>
            </div>
          </div>
        </div>
        <div style="padding-bottom:10px">
          <div class="email-set-row" style="padding:10px 0">
            <div
              class="email-set-option"
              style="width:100%;padding-right:38px;align-items:flex-start"
            >
              <div
                class="email-set-tit"
                style="width:auto"
                :class="{'linin-tit-en':$i18n.locale === 'en'}"
              >
                {{ $lang('public.gsEmailMsgContent', '消息内容') }}
                <span style="color:#F64D60">*</span>
              </div>
              <div style="flex-grow:1;min-height:0">
                <wml-editer
                  v-model="getterEmailItem.Body"
                  :config="{
                  height:380
                }"
                ></wml-editer>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <div class="email-btn-box">
      <el-button
        style="width:300px"
        type="primary"
        @click="doSave"
      >{{ $lang('common.saveBtn', '保存') }}</el-button>
    </div>
  </div>
</template>
<script>
import { mapGetters, mapActions } from 'vuex'
export default {
  data () {
    return {
      content: ''
    }
  },
  methods: {
    ...mapActions(['dispatchChangeLoading']),
    doSave () {
      if (!this.getterEmailItem.Theme || !this.getterEmailItem.Body) {
        this.$WmlMsg(this.$lang('public.gsEmailTitleBodyMust', '邮件标题与邮件内容必填'), 'warning')
        return
      }
      this.dispatchChangeLoading({ loading: true, tit: this.$lang('common.saveing', '保存中') })
      this.SharpObj.setTaskDefaultConfig(JSON.stringify(this.getterEmail), res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          this.$WmlMsg(this.$lang('common.saveSuccess', '保存成功！'))
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
        this.dispatchChangeLoading({ loading: false })
      })
    }
  },
  computed: {
    ...mapGetters(['getterEmail', 'getterEmailItem', 'getterLoading'])
  }
}
</script>
<style scoped>
.setDialog-main {
  width: 100%;
  height: 100%;
  padding: 17px;
}

.setDialog-main-box {
  height: 100%;
