  display: flex;
  flex-direction: column;
}

.setDialog-main >>> .el-tabs__content,
.setDialog-main >>> .el-tab-pane {
  height: 100%;
}

.email-wrap {
  width: 100%;
  height: 100%;
  overflow: auto;
}

.email-option {
  display: flex;
  align-items: center;
  padding: 10px 0;
}

.email-tit {
  width: 100px;
}

.email-set-box {
}

.email-set-row {
  display: flex;
  padding-bottom: 17px;
}

.email-set-option {
  display: flex;
  align-items: center;
}

.email-set-tit {
  /* width: 120px; */
  text-align: right;
  margin-right: 17px;
}

.email-btn-box {
  padding-top: 10px;
  text-align: center;
  flex-shrink: 0;
  margin-top: auto;
}

.linin-tit-left {
  text-align: left;
}

.panel-box {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.email-wrap-box {
  flex-grow: 1;
  width: 100%;
  overflow: hidden;
}

.email-success {
  color: #1bc4bd;
}

.email-fail {
  color: #f64d60;
}

.linin-tit-en {
  width: 140px !important;
}
</style>
