            <div class="email-set-row" style="padding-bottom:0px">
              <div class="email-set-option">
                <div
                  class="email-set-tit linin-tit-left"
                  style="width:auto;"
                >{{ $lang('public.gsFacebookCompanyMarketingLimit', '同一公司营销上限') }}</div>
                <div class="email-set-content">
                  <el-input-number
                    size="mini"
                    controls-position="right"
                    v-model="getterFacebookItem.CompanyLimit"
                  ></el-input-number>
                  <!-- <span style="margin-left:10px">{{ $lang('common.unit', '个') }}</span> -->
                </div>
              </div>
            </div>
          </div>
        </div>
        <div class="email-option">
          <div class="email-tit">
            <el-checkbox
              v-model="getterFacebookItem.IsAddFriend"
            >{{ $lang('public.gsFacebookFriendAdd', '好友添加') }}</el-checkbox>
          </div>
          <div class="email-content" style="flex-grow:1;">
            <div class="email-set-row" style="padding-bottom:0px">
              <div class="email-set-option">
                <div
                  class="email-set-tit linin-tit-left"
                  style="width:auto;margin:0 17px"
                >{{ $lang('public.gsFacebookCompanyFriendLimit', '同一公司好友添加上限') }}</div>
                <div class="email-set-content">
                  <el-input-number
                    size="mini"
                    controls-position="right"
                    v-model="getterFacebookItem.AddFriendLimit"
                  ></el-input-number>
                  <!-- <span style="margin-left:10px">{{ $lang('common.unit', '个') }}</span> -->
                </div>
              </div>
            </div>
          </div>
        </div>

        <el-divider content-position="left">{{ $lang('public.gsFacebookMsgSend', '信息发送') }}</el-divider>
        <div style="padding-bottom:10px">
          <el-checkbox
            style="margin-bottom:10px"
            v-model="getterFacebookItem.IsSendMessage"
          >{{ $lang('public.gsFacebookIsNoSend', '是否发送消息') }}</el-checkbox>
          <div class="email-set-row" style="padding:10px 0">
            <div class="email-set-option" style="width:100%;padding-right:38px">
              <div
                class="email-set-tit"
                style="width:auto"
              >{{ $lang('public.gsFacebookMsgContent', '消息内容') }}</div>
              <div style="flex-grow:1">
                <el-input
                  type="textarea"
                  v-model="getterFacebookItem.Message"
                  rows="10"
                  size="mini"
                ></el-input>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <div class="email-btn-box">
      <el-button
        style="width:300px"
        type="primary"
        @click="doSave"
      >{{ $lang('common.saveBtn', '保存') }}</el-button>
    </div>
  </div>
</template>
<script>
import { mapGetters, mapActions } from 'vuex'
export default {
  name: 'facebookGlobalSetting',
  data () {
    return {
      addIdentity: ''
    }
  },
  methods: {
    ...mapActions(['dispatchChangeLoading']),
    doSave () {
      this.dispatchChangeLoading({ loading: true, tit: this.$lang('common.saveing', '保存中') })
      this.SharpObj.setTaskDefaultConfig(JSON.stringify(this.getterFacebook), res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          this.$WmlMsg(this.$lang('common.saveSuccess', '保存成功！'))
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
        this.dispatchChangeLoading({ loading: false })
      })
    }
  },
  computed: {
    ...mapGetters(['getterFacebook', 'getterFacebookItem', 'getterLoading'])
  }
}
</script>
