<template>
  <div class="menu-main">
    <div style="display:none" v-popover:popoverdetail>{{ $lang('public.showTaskDetail', '显示任务详情') }}</div>
    <div v-show="!shortShow" class="menu-wrap">
      <div class="menu-top-box" style="-webkit-app-region:drag;">
        <img
          class="menu-img-box"
          src="@/assets/image/wmlLogoBg.png"
          style="-webkit-app-region:drag;"
        />
        <div class="menu-info-box" style="-webkit-app-region:no-drag;">
          <div class="menu-info-top">
            <div class="phone one-row">{{settingUserData.user.username}}</div>
            <div class="version">
              <i class="fa fa-eercast"></i>
              {{ $lang('public.internationalVersion', '国际版') }}
            </div>
          </div>
          <div class="menu-info-bottom" style="-webkit-app-region:no-drag;">
            <div class="current-package">
              <i class="el-icon-time"></i>
              <span>{{ $lang('public.ordinarySetmeal', '当前为普通套餐') }}(V{{getterVersion}})</span>
            </div>
          </div>
        </div>
      </div>
      <div class="menu-duty-box">
        <div class="duty-tit">{{ $lang('public.myTask', '我的任务') }}</div>
        <div class="duty-nav-icon">
          <i
            :class="item.className"
            v-for="(item, index) of leftIcon"
            :key="index"
            @click="handleLeftIcon(item.type)"
            :title="item.title"
          ></i>
        </div>
      </div>
      <div class="menu-contain-box">
        <ul class="contain-ul">
          <li
            class="contain-folder"
            @click="changeFolderBg(item)"
            v-for="(item, index) of folderData"
            :key="index"
          >
            <div class="contain-folder-tit-box" :class="{'folder-active':item.bgActive}">
              <div class="show-icon">
                <i
                  @click="changeFolderStatus(item)"
                  :class="{'el-icon-arrow-right':!item.active, 'el-icon-arrow-down':item.active}"
                ></i>
              </div>
              <div class="contain-folder-tit one-row">
                <i class="el-icon-folder"></i>
                <span>{{item.GroupName}}</span>
              </div>
              <div class="del-group-icon" @click.stop="delGroup(item, index)">
                <i class="el-icon-delete"></i>
              </div>
            </div>
            <div class="contain-file-box" v-show="item.active">
              <ul class="contain-duty-ul">
                <li
                  @contextmenu.prevent="showContextMenu($event, taskItem, item)"
                  class="contain-duty-option"
                  @click="selectDutyOption(item,taskItem)"
                  :class="{'bgActive':$route.fullPath === '/marketing/index/' + taskItem.Id}"
                  v-for="(taskItem, taskIndex) of item.Task"
                  :key="taskIndex"
                >
                  <div class="contain-duty-option-main">
                    <div class="contain-duty-option-icon">
                      <!-- <i class="fa fa-connectdevelop"></i> -->
                      <img
                        src="../../../assets/image/robotIcon.png"
                        style="cursor:pointer"
                        @click.stop="showTaskDetail(taskItem, $event)"
                      />
                    </div>
                    <div class="contain-duty-option-info">
                      <div class="duty-option-top">
                        <div class="duty-option-tit one-row">{{taskItem.TaskName}}</div>
                        <div
                          class="duty-option-status duty-option-status-start"
                          v-show="taskItem.Status == 0"
                        >
                          <img src="../../../assets/image/startIcon.png" alt />
                          <span>{{ $lang('public.taskStatus0', '待开始') }}</span>
                        </div>
                        <div
                          class="duty-option-status duty-option-status-running"
                          v-show="taskItem.Status == 1"
                        >
                          <img src="../../../assets/image/crawIcon.png" alt />
                          <span>{{ $lang('public.taskStatus1', '采集中') }}</span>
                        </div>
                        <div
                          class="duty-option-status duty-option-status-pause"
                          v-show="taskItem.Status == 2"
                        >
                          <img src="../../../assets/image/pauseIcon.png" alt />
                          <span>{{ $lang('public.taskStatus2', '采集暂停') }}</span>
                        </div>
                        <div
                          class="duty-option-status duty-option-status-finshed"
                          v-show="taskItem.Status == 3"
                        >
                          <img src="../../../assets/image/finshedIcon.png" alt />
                          <span>{{ $lang('public.taskStatus3', '采集完成') }}</span>
                        </div>
                        <div
                          class="duty-option-status duty-option-status-running"
                          v-show="taskItem.Status === 4"
                        >
                          <i class="el-icon-loading"></i>
                          <span>{{ $lang('public.taskStatus4', '营销中') }}</span>
                        </div>
                        <div
                          class="duty-option-status duty-option-status-pause"
                          v-show="taskItem.Status == 5"
                        >
                          <img src="../../../assets/image/pauseIcon.png" alt />
                          <span>{{ $lang('public.taskStatus5', '营销暂停') }}</span>
                        </div>
                        <div
                          class="duty-option-status duty-option-status-finshed"
                          v-show="taskItem.Status == 6"
                        >
                          <img src="../../../assets/image/finshedIcon.png" alt />
                          <span>{{ $lang('public.taskStatus6', '营销完成') }}</span>
                        </div>
                        <div
                          class="duty-option-status duty-option-status-running"
                          v-show="taskItem.Status == 7"
                        >
                          <img src="../../../assets/image/crawIcon.png" alt />
                          <span>{{ $lang('public.taskStatus7', '深度采集中') }}</span>
                        </div>
                        <div
                          class="duty-option-status duty-option-status-pause"
                          v-show="taskItem.Status == 8"
                        >
                          <img src="../../../assets/image/pauseIcon.png" alt />
                          <span>{{ $lang('public.taskStatus8', '深度采集暂停') }}</span>
                        </div>
                        <div
                          class="duty-option-status duty-option-status-finshed"
                          v-show="taskItem.Status == 9"
                        >
                          <img src="../../../assets/image/finshedIcon.png" alt />
                          <span>{{ $lang('public.taskStatus9', '深度采集完成') }}</span>
                        </div>
                      </div>
                      <div class="duty-option-bottom">
                        <div class="duty-option-data">
                          <span class="data-num-en">{{ $lang('public.dataNum', '数据条数：') }}</span>
                          <span class="duty-option-data-number">{{taskItem.ContactNumber}}</span>
                        </div>
                        <div class="duty-option-time one-row">
                          <span
                            :class="{'duty-time-en': $i18n.locale === 'en'}"
                          >{{taskItem.CreateTime}}</span>
                        </div>
                      </div>
                    </div>
                    <div class="contain-duty-option-close">
                      <i class="el-icon-close" @click.stop="delDuty(item, taskItem)"></i>
                    </div>
                  </div>
                </li>
              </ul>
            </div>
          </li>
        </ul>
        <div class="customer-service-box">
          <div class="customer-service" @click="go('https://www.waimaolang.cn')">
            <span>{{ $lang('public.yourCustomerService', '您的专属客服') }}</span>
          </div>
          <div
            class="customer-version"
          >{{ $lang('public.softwareVersion', '软件版本：') }}V{{getterVersion}}</div>
        </div>
      </div>
    </div>
    <div v-show="shortShow" class="menu-short-wrap">
      <div class="menu-short-top"></div>
      <ul class="menu-short-ul">
        <li
          class="menu-short-li"
          v-for="item of leftIcon"
          :key="item.type"
          @click="handleLeftIcon(item.type)"
        >
          <i :class="item.className" :title="item.title"></i>
        </li>
      </ul>
    </div>
    <el-popover v-model="detailPopover.show" ref="popoverdetail" trigger="click">
      <div class="detail-popover-box">
        <div class="detail-popover-option">
          <div
            class="detail-popover-tit"
            :class="{'detail-popover-entit':$i18n.locale === 'en'}"
          >{{ $lang('public.taskName', '任务名称') }}</div>
          <div
            class="detail-popover-content two-row"
            :title="detailPopover.taskItem.TaskName"
          >{{detailPopover.taskItem.TaskName}}</div>
          <div class="detail-popover-copy">
            <!-- <span @click="$copy(detailPopover.taskItem.TaskName)">复制</span> -->
          </div>
        </div>
        <!-- <div class="detail-popover-option">
          <div class="detail-popover-tit">任务状态</div>
          <div class="detail-popover-content two-row">
            <div
              class="duty-option-status duty-option-status-start"
              v-show="detailPopover.taskItem.Status == 0"
            >
              <span>待开始</span>
            </div>
            <div
              class="duty-option-status duty-option-status-running"
              v-show="detailPopover.taskItem.Status == 1"
            >
              <span>采集中</span>
            </div>
            <div
              class="duty-option-status duty-option-status-pause"
              v-show="detailPopover.taskItem.Status == 2"
            >
              <span>采集暂停</span>
            </div>
            <div
              class="duty-option-status duty-option-status-finshed"
              v-show="detailPopover.taskItem.Status == 3"
            >
              <span>采集完成</span>
            </div>
            <div
              class="duty-option-status duty-option-status-running"
              v-show="detailPopover.taskItem.Status === 4"
            >
              <i class="el-icon-loading"></i>
              <span>营销中</span>
            </div>
            <div
              class="duty-option-status duty-option-status-pause"
              v-show="detailPopover.taskItem.Status == 5"
            >
              <span>营销暂停</span>
            </div>
          </div>
          <div class="detail-popover-copy">
            <span @click="$copy(detailPopover.taskItem.TaskName)">复制</span>
          </div>
        </div>-->
        <div class="detail-popover-option">
          <div
            class="detail-popover-tit"
            :class="{'detail-popover-entit':$i18n.locale === 'en'}"
          >{{ $lang('public.dataNumAll', '数据总数') }}</div>
          <div
            class="detail-popover-content two-row"
            :title="detailPopover.taskItem.ContactNumber"
          >{{detailPopover.taskItem.ContactNumber}}</div>
          <div class="detail-popover-copy">
            <!-- <span @click="$copy(detailPopover.taskItem.ContactNumber)">复制</span> -->
          </div>
        </div>
        <div class="detail-popover-option">
          <div
            class="detail-popover-tit"
            :class="{'detail-popover-entit':$i18n.locale === 'en'}"
          >{{ $lang('public.searchArea', '搜索地区') }}</div>
          <div
            class="detail-popover-content two-row"
            :title="detailPopover.taskItem.CountryName"
          >{{detailPopover.taskItem.CountryName|filterCountry}}</div>
          <div class="detail-popover-copy">
            <!-- <span @click="$copy(detailPopover.taskItem.CountryName)">复制</span> -->
          </div>
        </div>
        <div class="detail-popover-option">
          <div
            class="detail-popover-tit"
            :class="{'detail-popover-entit':$i18n.locale === 'en'}"
          >{{ $lang('public.createTime', '创建时间') }}</div>
          <div
            class="detail-popover-content two-row"
            :title="detailPopover.taskItem.CreateTime"
          >{{detailPopover.taskItem.CreateTime}}</div>
          <div class="detail-popover-copy">
            <!-- <span @click="$copy(detailPopover.taskItem.CreateTime)">复制</span> -->
          </div>
        </div>
        <div class="detail-popover-option">
          <div
            class="detail-popover-tit"
            :class="{'detail-popover-entit':$i18n.locale === 'en'}"
          >{{ $lang('public.searchKeyWord', '搜索关键词') }}</div>
          <div
            class="detail-popover-content two-row"
            :title="detailPopover.taskItem.Keyword"
          >{{detailPopover.taskItem.Keyword|filterKeyword}}</div>
          <div class="detail-popover-copy">
            <span @click="$copy(detailPopover.taskItem.Keyword)">{{ $lang('common.copyBtn', '复制') }}</span>
          </div>
        </div>
        <div class="detail-popover-option">
          <div
            class="detail-popover-tit"
            :class="{'detail-popover-entit':$i18n.locale === 'en'}"
          >{{ $lang('public.filterKeyword', '排除关键词') }}</div>
          <div
            class="detail-popover-content two-row"
            :title="detailPopover.taskItem.RemoveKeyword"
          >{{detailPopover.taskItem.RemoveKeyword|filterRemoveKeyword}}</div>
          <div class="detail-popover-copy">
            <span
              @click="$copy(detailPopover.taskItem.RemoveKeyword)"
            >{{ $lang('common.copyBtn' , '复制') }}</span>
          </div>
        </div>
      </div>
    </el-popover>
    <transition name="el-zoom-in-top">
      <wml-mouse-menu
        :visible.sync="contextMenuShow"
        v-if="contextMenuShow"
        :menuList="menuList"
        :styleObj="menuStyle"
        @selectMenuItem="handleMenuItem"
      ></wml-mouse-menu>
    </transition>
  </div>
</template>

<script>
import { mapActions, mapGetters } from 'vuex'
export default {
  data () {
    return {
      menuStyle: {
        position: 'fixed',
        left: '0px',
        top: '0px',
        zIndex: 999999
      },
      menuList: [
        {
          class: 'iconfont icon-daochushuju',
          label: '导出数据',
          type: 'export'
        },
        {
          class: 'iconfont icon-kaishirenwu',
          label: '启动任务',
          type: 'startTask'
        },
        {
          class: 'iconfont icon-renwuzanting',
          label: '暂停任务',
          type: 'stopTask'
        },
        {
          class: 'iconfont icon-shanchurenwu',
          label: '删除任务',
          type: 'deleteTask'
        }
      ],
      contextMenuShow: false,
      settingUserData: {
        user: {
          username: '',
          version: {
            version: ''
          }
        }
      },
      leftIcon: [
        { className: 'el-icon-date', type: 'marketingChart', title: this.$lang('public.marketingChartTitle', '营销报表') }, // 营销数据报表
        { className: 'iconfont icon-tianjiafenzu', type: 'add', title: this.$lang('public.addGroupTitle', '添加分组') },
        { className: 'iconfont icon-quanjupeizhi', type: 'setting', title: this.$lang('public.globalConfigTitle', '全局配置') },
        { className: 'iconfont icon-shujujiaohuanzixitong-shujushouquan', type: 'empower', title: this.$lang('public.empowerListTitle', '授权列表') }
      ],
      detailPopover: {
        show: false,
        taskItem: {
          TaskName: '',
          Keyword: '',
          CountryName: '',
          RemoveKeyword: ''
        }
      },
      rightMenuItem: {},
      rightMenuGroup: {}
    }
  },
  computed: {
    ...mapGetters(['getterVersion', 'getterMarketingData', 'changeTaskStatus', 'visitedViews']),
    folderData () {
      return this.$store.state.common.TaskList
    }
  },
  props: {
    shortShow: {
      default: false,
      type: Boolean
    }
  },
  methods: {
    ...mapActions(['taskDetailInfoDispatch']),
    /**
     * @author: vince.Liang
     * @function: 添加任务组抛出handleLeftIcon事件
     * @data: 2019-3-27
     * @param {String} type 各个图标对应的标识
     * @return:undefined
     */
    handleLeftIcon (type) {
      this.$emit('handleLeftIcon', type)
    },

    /**
     * @author: vince.Liang
     * @function: 切换文件夹列表背景色
     * @data: 2019-3-27
     * @param {Object} item 当前操作的文件夹
     * @return:undefined
     */
    changeFolderBg (item) {
      for (var i = 0; i < this.folderData.length; i++) {
        this.$set(this.folderData[i], 'bgActive', false)
      };
      item.bgActive = true
    },

    /**
     * @author: vince.Liang
     * @function: 切换文件夹列表展开状态
     * @data: 2019-3-27
     * @param {Object} item 当前操作的文件夹
     * @return:undefined
     */
    changeFolderStatus (item) {
      if (item.active) {
        this.$set(item, 'active', false)
      } else {
        this.$set(item, 'active', true)
      }
    },

    /**
     * @author: vince.Liang
     * @function: 跳转对应的任务详情页
     * @data: 2019-3-27
     * @param {Object} item 当前操作的分组数据
     * @param {Object} taskItem 当前操作的任务数据
     * @return:undefined
     */
    selectDutyOption (item, taskItem) {
      let num = 0
      for (let item of this.visitedViews) {
        if (item.name === 'marketing_index') {
          num++
        }
      }
      if (num >= 8) {
        this.$WmlMsg('最多同时打开8个任务', 'warning')
        return
      }
      this.taskDetailInfoDispatch({ groupName: item.GroupName, taskName: taskItem.TaskName })
      this.$to({ path: '/marketing/index/' + taskItem.Id })
    },

    /**
     * @author: vince.Liang
     * @function: 删除任务
     * @data: 2019-3-27
     * @param {Array} item 当前操作的分组的所有任务数据
     * @param {Object} taskItem 当前操作的任务数据
     * @return:undefined
     */
    async delDuty (item, taskItem) {
      if (!await this.$WmlConfirm(`${this.$lang('public.deleteTaskConfirmTip0', '此操作将永久删除')} ${taskItem.TaskName} ${this.$lang('public.deleteTaskConfirmTip1', '任务，是否继续？')}`)) { return }
      this.SharpObj.deleteTask(taskItem.Id, res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          let { length } = item.Task
          this.$bus.$emit('delTask', taskItem)
          for (let i = 0; i < length; i++) {
            if (item.Task[i].Id === taskItem.Id) {
              item.Task.splice(i, 1)
              this.$store.dispatch('delVisitedView', { fullPath: `/marketing/index/${taskItem.Id}` }).then(router => {
                this.$route.path === `/marketing/index/${taskItem.Id}` && this.$router.push(router[router.length - 1].path)
              })
              break
            }
          }
          this.$WmlMsg(this.$lang('public.dedleteSuccessTip', '删除成功！'))
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: 删除对应分组
     * @data: 2019-3-27
     * @param {Object} item 当前操作的分组数据
     * @param {Number} index 当前操作的分组的位置
     * @return:undefined
     */
    async delGroup (item, index) {
      if (!await this.$WmlConfirm(`${this.$lang('public.deleteGroupConfirmTip0', '此操作将永久删除')} ${item.GroupName} ${this.$lang('public.deleteGroupConfirmTip1', '分组，是否继续？')}`)) { return }
      this.SharpObj.deleteGroup(item.Id, async res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          this.$bus.$emit('delGroup', item)
          if (item.Task && item.Task.length > 0) {
            for (let taskItem of item.Task) {
              await this.$store.dispatch('delVisitedView', { fullPath: `/marketing/index/${taskItem.Id}` }).then(router => {
                this.$route.path === `/marketing/index/${taskItem.Id}` && this.$router.push(router[router.length - 1].path)
              })
            }
          }
          this.folderData.splice(index, 1)
          this.$WmlMsg(this.$lang('public.dedleteSuccessTip', '删除成功！'))
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: 展示任务详情弹出框
     * @param {Object} taskItem 当前操作的任务数据
     * @param {domObject} event 当前操作的dom对象
     * @return: undefined
     */
    showTaskDetail (taskItem, event) {
      if (this.detailPopover.show && this.detailPopover.taskItem.Id === taskItem.Id) {
        this.detailPopover.show = false
        return
      }
      this.detailPopover.show = true
      this.detailPopover.taskItem = JSON.parse(JSON.stringify(taskItem))
      // if (this.detailPopover.taskItem.RemoveKeyword) {
      //   let removeKey = ''
      //   this.detailPopover.taskItem.RemoveKeyword = JSON.parse(this.detailPopover.taskItem.RemoveKeyword)
      //   for (let item of this.detailPopover.taskItem.RemoveKeyword) {
      //     removeKey = removeKey + item + ','
      //   }
      //   removeKey = removeKey.substring(0, removeKey.length - 1)
      //   this.detailPopover.taskItem.RemoveKeyword = removeKey
      // }
      this.$nextTick(() => {
        var pop = this.$refs['popoverdetail']
        pop.popperJS._reference = event.target
        pop.popperJS.state.position = pop.popperJS._getPosition(pop.popperJS._popper, pop.popperJS._reference)
        pop.popperJS.update()
      })
    },
    go (url) {
      window.open(url)
    },
    showContextMenu (e, taskItem, groupItem) {
      // console.log(e)
      Object.assign(this.menuStyle, {
        left: e.clientX + 'px',
        top: e.clientY + 'px'
        // bottom: '0px'
      })
      !this.contextMenuShow && (this.contextMenuShow = true)
      Object.assign(this.rightMenuItem, taskItem)
      Object.assign(this.rightMenuGroup, groupItem)
    },
    handleMenuItem (type) {
      switch (type) {
        case 'export':
          this.taskDetailInfoDispatch({ taskName: this.rightMenuItem.TaskName })
          this.$to({ path: `/task/export/${this.rightMenuItem.Id}` })
          break
        case 'startTask':
          let validate = this.$WmlValidator.validate(this.rightMenuItem.Status, [
            {
              rule: 'isInclude:[1, 4, 7]',
              errorMsg: '当前任务正在运行中'
            }
          ])
          if (validate) {
            this.$WmlMsg(validate, 'warning')
            return
          }
          this.SharpObj.getTaskConfig(Number(this.rightMenuItem.Id), res => {
            res = JSON.parse(res)
            if (res.Code === 0) {
              this.SharpObj.startTask(JSON.stringify(res.Data.Config), result => {
                result = JSON.parse(result)
                if (result.Code === 0) {
                  this.$to({ path: `/marketing/index/${this.rightMenuItem.Id}` })
                  this.changeTaskStatus(Number(this.rightMenuItem.Id), result.Data.Status)
                  // 任务开始
                  this.$WmlMsg(this.$t('marketing.taskStart'))
                } else {
                  this.$WmlMsg(result.Msg, 'warning')
                }
              })
            } else {
              throw res.Msg
            }
          })
          break
        case 'stopTask':
          let validateStop = this.$WmlValidator.validate(this.rightMenuItem.Status, [
            {
              rule: 'isNoInclude:[1, 4, 7]',
              errorMsg: '当前任务未运行'
            }
          ])
          if (validateStop) {
            this.$WmlMsg(validateStop, 'warning')
            return
          }
          this.getterMarketingData(this.rightMenuItem.Id).stopping = true
          this.SharpObj.stopTask(Number(this.rightMenuItem.Id), res => {
            res = JSON.parse(res)
            if (res.Code === 0) {
              this.getterMarketingData(this.rightMenuItem.Id).stopping = false
              this.changeTaskStatus(this.rightMenuItem.Id, res.Data.Status)
              this.$to({ path: `/marketing/index/${this.rightMenuItem.Id}` })
              // 任务暂停成功
              this.$WmlMsg(this.$t('marketing.taskStopSuccess'))
            } else {
              this.$WmlMsg(res.Msg, 'warning')
            }
          })
          break
        case 'deleteTask':
          this.delDuty(this.rightMenuGroup, this.rightMenuItem)
          break
      }
    }
  },
  filters: {
