<script>
import { mapGetters, mapActions } from 'vuex'
export default {
  name: 'linkedinGlobalSetting',
  data () {
    return {
      addIdentity: ''
    }
  },
  methods: {
    ...mapActions(['dispatchChangeLoading']),
    removeIdentityList (index) {
      this.getterLinkedinItem.IdentityList.splice(index, 1)
    },
    init () {
      if (Array.isArray(this.getterLinkedinItem.IdentityList) && this.getterLinkedinItem.IdentityList.length > 0) {
        let identity = ''
        for (let item of this.getterLinkedinItem.IdentityList) {
          identity = identity + item + '\n'
        }
        this.addIdentity = identity.substring(0, identity.length - 1)
      } else {
        this.addIdentity = ''
      }
    },
    doAddIdentity () {
      if (this.addIdentity === '' || this.addIdentity === '\n') {
        this.getterLinkedinItem.IdentityList = []
      }
      let keyWordCustom = this.addIdentity.split(/\n/)
      keyWordCustom = keyWordCustom.filter((item, index) => {
        if (item === '' || keyWordCustom.indexOf(item) !== index) {
          return false
        } else {
          return true
        }
      })
      this.getterLinkedinItem.IdentityList = keyWordCustom
    },
    doSave () {
      this.dispatchChangeLoading({ loading: true, tit: this.$lang('common.saveing', '保存中') })
      this.SharpObj.setTaskDefaultConfig(JSON.stringify(this.getterLinkedin), res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          this.$WmlMsg(this.$lang('common.saveSuccess', '保存成功！'))
        } else {
          this.$WmlMsg(res.Msg, 'warning')
        }
        this.dispatchChangeLoading({ loading: false })
      })
    }
  },
  computed: {
    ...mapGetters(['getterLinkedin', 'getterLinkedinItem', 'getterLoading'])
  },
  created () {
    this.init()
  }
}
</script>
