<template>
  <div class="main">
    <div v-popover:popoverset style="display:none"></div>
    <el-popover
      popper-class="popover-set-tagsview"
      style="padding:0"
      width="100"
      v-model="popoverSet"
      trigger="click"
      ref="popoverset"
    >
      <div class="set-wrap">
        <div class="set-box">
          <div
            class="set-option"
            v-for="(item, index) of setOption"
            :key="index"
            @click="handleSetSelect(item)"
          >
            <i :class="item.iconClass"></i>
            <span>{{ item.label }}</span>
          </div>
        </div>
      </div>
    </el-popover>
    <div class="tag-wrap">
      <div
        :class="{active:item.path === $route.fullPath}"
        class="tag-option"
        v-for="(item, index) of visitedViews"
        :key="item.path + index"
        @click="goRouter(item)"
      >
        <i :class="item.meta.icon"></i>
        <div
          class="tag-label one-row"
          v-if="item.groupName !== '' && item.taskName !== ''"
          :title="item.groupName + ' | ' + item.taskName"
        >
          {{item.groupName}}
          <span style="margin:0 3px">|</span>
          {{item.taskName}}
        </div>
        <div
          class="tag-label one-row"
          v-if="item.groupName === '' && item.taskName !== ''"
          :title="item.groupName + ' | ' + item.taskName"
        >
          {{item.title}}
          <span style="margin:0 3px">|</span>
          {{item.taskName}}
        </div>
        <div
          class="tag-label one-row"
          v-if="item.groupName === '' && item.taskName === ''"
          :title="$lang(item.title)"
        >{{$lang(item.title)}}</div>
        <i class="el-icon-close close" @click.stop="delRouter(item)" v-if="item.meta.showClose"></i>
      </div>
      <div style="height:100%;flex-grow:1;-webkit-app-region:drag;" @dblclick="doNarrow"></div>
    </div>
    <div class="nav-wrap">
      <i
        v-for="(item,index) in iconData"
        :key="index"
        :class="item.class"
        @click.stop="tagIconClick(item, $event)"
      ></i>
    </div>
    <upgrade :visible.sync="upgrade.show" :newVersionData="upgrade.versionData"></upgrade>
  </div>
</template>

<script>
import upgrade from '@/home/upgrade/index.vue'
import { mapGetters, mapActions } from 'vuex'
export default {
  name: 'tagsView',
  components: { upgrade },
  data () {
    return {
      popoverSet: false,
      setOption: [
        {
          iconClass: 'iconfont icon-shujubeifen',
          label: '数据备份',
          type: 'backup'
        },
        {
          iconClass: 'iconfont icon-data-restore',
          label: '数据还原',
          type: 'reduction'
        },
        {
          iconClass: 'iconfont icon-shezhizhongxin',
          label: '设置中心',
          type: 'setting'
        },
        {
          iconClass: 'iconfont icon-gengxinjilu',
          label: '历史版本',
          type: 'version'
        },
        {
          iconClass: 'iconfont icon-jianchagengxin',
          label: '检查更新',
          type: 'update'
        }
      ],
      upgrade: {
        show: false,
        versionData: {
          vesion: '1.0.0.9',
          versionRemark: '',
          IsForceUpdate: false,
          IsUpdate: false
        }
      }
    }
  },
  props: {
    iconData: {
      type: Array,
      default: () => { return [] }
    }
  },
  methods: {
    ...mapActions(['dispatchDeleteTask']),
    /**
     * @author: vince.Liang
     * @function:根据路由动态添加标签的事件
     * @data: 2019-3-27
     * @param {type}
     * @return:
     */
    addViewTags () {
      const { name } = this.$route
      if (name) {
        this.$store.dispatch('addView', this.$route)
      }
      return false
    },

    /**
     * @author: vince.Liang
     * @function: 路由跳转
     * @data: 2019-3-27
     * @param {type}
     * @return:
     */
    goRouter (item) {
      item.path && this.$router.push(item.path)
    },

    /**
     * @author: vince.Liang
     * @function: 关闭标签删除对应标签的vuex数据以及跳转对应路由
     * @data: 2019-3-27
     * @param {type}
     * @return:
     */
    delRouter (item) {
      if (item.name === 'marketing_index') {
        this.SharpObj.getTaskIsExecute(Number(item.params.id), res => {
          res = JSON.parse(res)
          if (res.Code !== 0) {
            this.$WmlMsg(res.Msg, 'warning')
            return
          }
          this.$store.dispatch('delVisitedView', item).then(router => {
            item.path === this.$route.path && this.$router.push(router[router.length - 1].path)
          })
          let timer = window.setTimeout(() => {
            this.$socket.off(item.params.id)
            this.$delete(this.getterTest[Number(item.params.id)], 'taskDataTable')
            this.$delete(this.getterTest, Number(item.params.id))
            clearTimeout(timer)
            timer = null
          }, 0)
        })
      } else {
        this.$store.dispatch('delVisitedView', item).then(router => {
          item.path === this.$route.path && this.$router.push(router[router.length - 1].path)
        })
      }
    },

    /**
     * @author: vince.Liang
     * @function: 点击顶部栏右边的图标向外抛出tagIconClick
     * @data: 2019-3-27
     * @param {type}
     * @return:
     */
    tagIconClick (item, $event) {
      if (item.type === 'setting') {
        this.popoverSet = true
        this.$nextTick(() => {
          var pop = this.$refs['popoverset']
          pop.popperJS._reference = $event.target
          pop.popperJS.state.position = pop.popperJS._getPosition(pop.popperJS._popper, pop.popperJS._reference)
          pop.popperJS.update()
        })
        return
      }
      this.$emit('tagIconClick', item)
    },

    /**
     * @author: vince.Liang
     * @function: 双击缩小
     * @data: 2019-3-27
     * @param {type}
     * @return:
     */
    doNarrow () {
      this.SharpObj.maxOrMinForm()
    },

    handleSetSelect (item) {
      console.log(item)
      switch (item.type) {
        case 'setting':
          this.$emit('tagIconClick', item)
          break
        case 'version':
          this.$to({ path: '/setting/version' })
          break
        case 'update':
          this.SharpObj.getUpdateInfo(res => {
            res = JSON.parse(res)
            if (res.Code !== 0) {
              this.$WmlMsg(res.Msg, 'warning')
              return
            }
            Object.assign(this.upgrade.versionData, res.Data)
            this.upgrade.show = true
          })
          break
        case 'backup':
          this.SharpObj.backups(res => {
            console.log(res)
            res = JSON.parse(res)
            if (res.Code !== 0) {
              this.$WmlMsg(res.Msg, 'warning')
              return
            }
            if (res.Msg !== '') {
              this.$WmlMsg(res.Msg)
            }
          })
          break
        case 'reduction':
          this.SharpObj.recovery(res => {
            res = JSON.parse(res)
            if (res.Code !== 0) {
              this.$WmlMsg(res.Msg, 'warning')
              return
            }
            if (res.Msg !== '') {
              this.$confirm(res.Msg, '提示', {
                confirmButtonText: '确定',
                type: 'warning',
                showClose: false,
                showCancelButton: false,
                closeOnClickModal: false,
                closeOnPressEscape: false
              }).then(() => {
                this.$emit('close-win')
              })
            }
          })
          break
      }
      this.popoverSet = false
    }
  },
  computed: {
    ...mapGetters(['visitedViews', 'getterTest'])
  },
  watch: {
    $route () {
      this.addViewTags()
    }
  },
  created () {
    this.addViewTags()
  }
}
</script>

<style scoped>
.main {
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: space-between;
}
.tag-wrap {
  height: 100%;
  overflow: auto;
  display: flex;
  flex-wrap: nowrap;
  flex-grow: 1;
  overflow-y: hidden;
}
.nav-wrap {
  height: 100%;
  margin-right: 7px;
  display: flex;
  justify-content: flex-end;
  align-items: center;
  flex-shrink: 0;
}

.nav-wrap > i {
  cursor: pointer;
  padding: 8px;
}

.nav-wrap > i:hover {
  background-color: #dbe1e7;
}

.tag-option {
  width: 130px;
  height: 100%;
  flex-shrink: 0;
  display: flex;
  justify-content: space-around;
  align-items: center;
  background-color: #d8dde4;
  margin-right: 1px;
  padding: 0 3px;
}
.tag-label {
  width: 100px;
  margin: 0 3px;
  color: #3b3d3f;
  font-size: 12px;
  text-align: center;
  cursor: pointer;
}

.tag-option > i {
  font-size: 16px;
  color: #9da1a6;
}

.active {
  background-color: #0daeff;
}

.active > .tag-label,
.active > i {
  color: #fff;
}

.close {
  cursor: pointer;
}

.close:hover {
  color: #353738;
}

.set-option {
  padding: 7px 0;
  width: 100%;
  display: flex;
  align-items: center;
  margin-bottom: 3px;
  cursor: pointer;
}

.set-option:last-child {
  margin-bottom: 0;
}

.set-option:hover {
  background-color: #0daeff;
}

.set-option:hover i,
.set-option:hover span {
  color: #fff;
}

.set-option i {
  font-size: 16px;
  margin: 0 12px;
}
</style>

<style>
.popover-set-tagsview {
  padding: 3px 0 !important;
}
</style>
