<template>
  <div style="height:100%">
    <div style="width:100%;height:10px;background-color:#E8EFF4;-webkit-app-region:drag;"></div>
    <el-container class="admin-main main">
      <el-aside width="auto" style="overflow: unset;" class="wml-left-nav">
        <left-nav @handleLeftIcon="handleLeftIcon" />
      </el-aside>
      <el-container>
        <el-header
          height="45px"
          style="line-height:40px;border-left: 1px solid #d6d6d6;padding:0;background-color:#E8EFF4;padding:0"
        >
          <tags-view :iconData="iconData" @tagIconClick="tagIconClick" @close-win="closeWindowsNow"></tags-view>
        </el-header>
        <el-main class="right-content">
          <transition name="el-fade-in-linear">
            <router-view v-if="showRouterView" class="routerView" ref="routerView"></router-view>
          </transition>
        </el-main>
      </el-container>
      <wml-dialog
        :visible.sync="taskGroupShow"
        :title="$lang('public.createTaskGroup', '创建任务组')"
        :drag="true"
        width="380px"
        class="wml-dialog-box"
      >
        <el-form ref="form" @submit.native.prevent>
          <el-form-item>
            <el-input
              ref="task-input"
              v-model="taskName"
              @keyup.enter.native="createTaskGroup"
              clearable
              :placeholder="$lang('public.inputGroupNameTip', '请输入组名')"
              size="mini"
            ></el-input>
          </el-form-item>
          <div style="text-align:center">
            <el-button
              style="padding-left:60px;padding-right:60px"
              type="primary"
              size="mini"
              @click="createTaskGroup"
              :disabled="taskName ==''"
            >{{ $lang('public.ensureBtn', '确定') }}</el-button>
          </div>
        </el-form>
      </wml-dialog>
      <transition name="el-zoom-in-center">
        <wml-dialog
          :title="$lang('public.globalSettingTit', '全局设置')"
          width="880px"
          v-if="globalSettingShow"
          :visible.sync="globalSettingShow"
          customClass="global-setting-dialog"
        >
          <global-setting-popup></global-setting-popup>
        </wml-dialog>
      </transition>
      <el-drawer custom-class="drawer-product-info" :visible.sync="visible" :with-header="false">
        <product-info></product-info>
      </el-drawer>
    </el-container>
  </div>
</template>

<script>
import productInfo from '@/home/public/components/productInfo'
import leftNav from './components/leftNav'
import { mapActions, mapGetters } from 'vuex'
import globalSettingPopup from '@/home/public/components/globalSettingsPopup'
import tagsView from './components/tagsView'
export default {
  components: { productInfo, leftNav, tagsView, globalSettingPopup },
  data () {
    return {
      iconData: [// 多窗口组件的icon数据
        { class: 'el-icon-user', type: 'user' }, // 打开产品信息弹窗
        { class: 'el-icon-setting', type: 'setting' }, // 跳设置
        { class: 'el-icon-minus', type: 'minimize' }, // 最小化
        { class: 'el-icon-full-screen', type: 'maximize' }, // 最大化
        { class: 'el-icon-close', type: 'closeWindow' } // 关闭窗口
      ],
      taskGroupShow: false, // 新增分组的弹窗
      taskName: '', // 新增分组名
      loading: false,
      taskId: '',
      showRouterView: true,
      globalSettingShow: false,
      visible: false
    }
  },
  provide () {
    return {
      reload: this.reload,
      // 向所有的子孙组件注入一个依赖，打开添加分组弹窗（主要在创建任务流程时使用）
      openAddGroup: this.openAddGroup
    }
  },
  computed: {
    // vuex任务列表getter
    ...mapGetters(['TaskListGetter'])
  },
  created () {
    this.getAllGroupAndTask()
    window.changeBrowserIcon = this.changeBrowserIcon
    this.$socket.on('taskIndicators', res => {
      this.dispatchTaskIndicators(res.detail.Data)
    })
    this.SharpObj.maxForm(res => {
      for (let item of this.iconData) {
        if (item.maximize === 'maximize') {
          item.class = 'el-icon-setting'
          if (res) {
            item.class = 'el-icon-copy-document'
          } else {
            item.class = 'el-icon-full-screen'
          }
        }
      }
    })
  },

  methods: {
    // 设置vuex任务列表方法
    ...mapActions([
      'TaskListDispatch',
      'dispatchChangeLoading',
      'dispatchAction',
      'dispatchEmail',
      'dispatchLinkedin',
      'dispatchTwitter',
      'dispatchFacebook',
      'dispatchInstagram',
      'dispatchTaskIndicators'
    ]),
    /**
   * @author: vince.Liang
   * @function: 打开添加分组弹窗的方法，主要提供给子孙组件调用
   * @data: 2019-3-27
   * @param {none}
   * @return:undefined
   */
    openAddGroup () {
      this.taskGroupShow = true
    },

    /**
     * @author: vince.Liang
     * @function: 向外抛出reload事件以改变showRouterView
     * @data: 2019-3-27
     * @param {none}
     * @return:undefined
     */
    reload () {
      this.showRouterView = false
      this.$nextTick(() => {
        this.showRouterView = true
      })
    },

    /**
     * @author: vince.Liang
     * @function: 窗口组件右边的icon事件
     * @data: 2019-3-27
     * @param {none}
     * @return:undefined
     */
    tagIconClick (item) {
      if (item.type === 'setting') {
        this.$to({ path: '/setting/index' })
      } else if (item.type === 'minimize') {
        this.SharpObj.minForm()
      } else if (item.type === 'maximize') {
        this.SharpObj.maxForm(res => {
          item.class = 'el-icon-setting'
          if (res) {
            item.class = 'el-icon-copy-document'
          } else {
            item.class = 'el-icon-full-screen'
          }
        })
      } else if (item.type === 'closeWindow') {
        this.closeWindows()
      } else if (item.type === 'user') {
        this.visible = !this.visible
      }
    },

    /**
     * @author: vince.Liang
     * @function: 处理左边tab栏顶部的图标点击事件
     * @data: 2019-3-27
     * @param {String} type 图标标识
     * @return: undefined
     */
    handleLeftIcon (type) {
      switch (type) {
        case 'setting':
          this.SharpObj.getTaskDefaultConfig(res => {
            res = JSON.parse(res)
            if (res.Code !== 0) {
              this.$WmlMsg(res.Msg, 'warning')
              return
            }
            this.dispatchAction(res.Data.Action)
            this.dispatchEmail(res.Data.Email)
            this.dispatchLinkedin(res.Data.LinkedIn)
            this.dispatchTwitter(res.Data.Twitter)
            this.dispatchFacebook(res.Data.Facebook)
            this.dispatchInstagram(res.Data.Instagram)
            this.dispatchChangeLoading({ loading: false })
            this.globalSettingShow = !this.globalSettingShow
          })
          break
        case 'add':
          this.taskGroupShow = !this.taskGroupShow
          break
        case 'empower':
          this.SharpObj.showSocialLogin(res => {
            res = JSON.parse(res)
            if (res.Code !== 0) {
              this.$WmlMsg(res.Msg, 'warning')
            }
          })
          break
        case 'marketingChart':
          this.$to({ path: '/marketing/reportchart' })
      }
    },

    /**
    * @author: vince.Liang
    * @function: 关闭软件
    * @data: 2019-3-27
    * @param {type}
    * @return:undefined
    */
    async closeWindows () {
      this.SharpObj.isCloseMainFrm(async res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        if (res.Data) {
          let confirm
          try {
            confirm = await this.$confirm(this.$lang('common.closeTipBody', '确定关闭程序吗？'), this.$lang('common.confirmTipTitle', '提示'), {
              confirmButtonText: this.$lang('common.confirmButtonText', '确定'),
              cancelButtonText: this.$lang('common.cancelButtonText', '取消'),
              type: 'warning',
              customClass: 'no-drag'
            })
          } catch (error) {
            confirm = error
          }
          if (confirm !== 'confirm') return
          this.changeOrJudgeDutyList(this.TaskListGetter)
          this.$loading({
            text: this.$lang('common.closingProgram', '关闭程序中'),
            spinner: 'el-icon-loading',
            background: 'rgba(255,255,255, .7)'
          })
          window.setTimeout(() => {
            this.SharpObj.closeForm()
          }, 600)
        } else {
          this.SharpObj.closeForm()
        }
      })
    },
    closeWindowsNow () {
      this.changeOrJudgeDutyList(this.TaskListGetter)
      this.$loading({
        text: this.$lang('common.closingProgram', '关闭程序中'),
        spinner: 'el-icon-loading',
        background: 'rgba(255,255,255, .7)'
      })
      window.setTimeout(() => {
        this.SharpObj.closeForm()
      }, 600)
    },

    /**
     * @author: vince.Liang
     * @function: 添加任务组
     * @data: 2019-3-27
     * @param {type}
     * @return:
     */
    async createTaskGroup () {
      if (!this.taskName) {
        return
      }
      this.$refs['task-input'].blur()
      let confirm
      try {
        confirm = await this.$confirm(`${this.$lang('public.addGroupTip0', '确定添加组名为')} ${this.taskName} ${this.$lang('public.addGroupTip1', '的分组吗？')}`, this.$lang('common.confirmDefaultTitle', '提示'), {
          confirmButtonText: this.$lang('common.confirmDefaultBtnConfirmText', '确定'),
          cancelButtonText: this.$lang('common.confitmDefaultBtnCancelText', '取消'),
          type: 'warning'
        })
      } catch (error) {
        confirm = error
        this.$WmlMsg(this.$lang('public.cancelAddGroup', '已取消添加分组'), 'info')
      }
      if (confirm !== 'confirm') return
      this.SharpObj.newGroup(this.taskName, res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          this.TaskListGetter.push({ ...res.Data, Task: [] })
          this.taskGroupShow = false
          // 创建任务组成功自动选择该任务组
          this.$bus.$emit('selectGroup', res.Data.Id)
          this.$WmlMsg(`${this.$lang('public.addGroupSuccessTip0', '成功添加')} ${this.taskName} ${this.$lang('public.addGroupSuccessTip1', '分组！')}`)
          this.taskName = ''
          if (this.$route.name !== 'task_index' && this.$route.name !== 'home_index') {
            this.$to({ path: '/home/index' })
          }
        } else {
          this.$WmlMsg(`${this.$lang('public.getTaskGroupListFailWarning', '获取分组以及任务列表警告，原因：')}${res.data.Msg}`, 'warning')
        }
      })
    },

    /**
     * @author: vince.Liang
     * @function: 关闭时改变运行中的任务状态
     * @data: 2019-3-27
     * @param {type}
     * @return:
     */
    changeOrJudgeDutyList (taskList) {
      for (var i = 0; i < taskList.length; i++) {
        if (taskList[i].children !== undefined) {
          for (var j = 0; j < taskList[i].children.length; j++) {
            if (taskList[i].children[j].status === 1) {
              this.SharpObj.modifyTaskStatus(JSON.stringify({ taskId: Number(taskList[i].children[j].taskId), status: 2 }), res => {
                res = JSON.parse(res)
                res.code === 0 ? taskList[i].children[j].status = 2 : this.$WmlMsg(res.msg, 'warning')
              })
            }
          }
        }
      }
    },

    /**
     * @author: vince.Liang
     * @function: 初始化获取所有的分组以及任务列表
     * @data: 2019-3-27
     * @param {type}
     * @return:
     */
    getAllGroupAndTask () {
      this.SharpObj.getAllGroupAndTask(res => {
        res = JSON.parse(res)
        if (res.Code === 0) {
          let taskList = []
          for (let item of res.Data) {
            taskList.push({ ...item.Group, Task: item.Task })
          }
          this.TaskListDispatch(taskList)
        } else {
          this.$WmlMsg(`${this.$lang('public.getTaskGroupListFailWarning', '获取分组以及任务列表警告，原因：')}${res.data.Msg}`, 'warning')
        }
      })
    },

    /**
   * @author: vince.Liang
   * @function: 提供c#页面最大化正常化改变窗口图标
   * @param {Boolean} type 当前页面的状态，true为最大化、false为正常化
   * @return: undefined
   */
    changeBrowserIcon (type) {
      for (let item of this.iconData) {
        if (item.type === 'maximize') {
          if (type) {
            item.class = 'el-icon-copy-document'
          } else {
            item.class = 'el-icon-full-screen'
          }
          break
        }
      }
    }
  }
}

</script>
<style>
.el-container {
  text-align: left;
}
.main-height {
  position: relative;
  height: 100%;
}

.global-setting-dialog .el-scrollbar__wrap {
  overflow: auto;
}
.global-setting-dialog {
  display: flex;
  flex-direction: column;
  margin: 0 !important;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  height: 700px;
  max-height: calc(100% - 30px);
  max-width: calc(100% - 30px);
}
.global-setting-dialog .el-dialog__body {
  flex: 1;
  overflow: auto;
}
</style>
<style scoped>
.admin-main {
  display: flex;
  height: calc(100% - 10px);
  background-color: #e8eff4;
}
.left-nav {
  height: 100%;
}
.right-content {
  position: relative;
  flex-grow: 1;
  background: #f5f6fa;
  box-shadow: inset 0 0 8px 0px #ccc;
  height: 100%;
  padding: 10px;
}

.main >>> .el-dialog__header {
  border-bottom: 1px solid #e3e6ed;
  background-color: #f3f3f3;
  padding: 12px 20px;
}

.main >>> .el-dialog__headerbtn {
  top: 17px;
}

.main >>> .el-dialog__headerbtn .el-dialog__close {
  font-size: 20px;
}
.main >>> .drawer-product-info {
  width: 360px !important;
}
</style>
